from collections import Counter
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
# rule: every full same-color rectangle >= 3x3 gets interior filled; the earlier wrong submit was my first attempt.
# But summary says solve matched demo. Reconstruct that exact solver and verify, then apply to test.
def f(g):
    h=len(g); w=len(g[0]); bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    seen=[[False]*w for _ in range(h)]; out=[r[:] for r in g]
    for i in range(h):
        for j in range(w):
            if not seen[i][j] and g[i][j]!=bg:
                c=g[i][j]; st=[(i,j)]; cells=[]
                while st:
                    y,x=st.pop()
                    if seen[y][x]: continue
                    seen[y][x]=True; cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and g[ny][nx]==c:
                            st.append((ny,nx))
                ys=[p[0] for p in cells]; xs=[p[1] for p in cells]
                t,b=min(ys),max(ys); l,r=min(xs),max(xs)
                if len(cells)==(b-t+1)*(r-l+1) and b-t>=2 and r-l>=2:
                    for y in range(t+1,b):
                        for x in range(l+1,r):
                            out[y][x]=2
    return out
